from pathlib import Path
import re

path = Path('recursos/insights.html')
s = path.read_text(encoding='utf-8')

# Remove prior axis override generated by this script.
s = re.sub(r'\n?<style id="insights-topic-axis-fix-v2">.*?</style>\s*', '\n', s, flags=re.S)

override = r'''
<style id="insights-topic-axis-fix-v2">
.insights-topic-nav .container{
  width:min(1480px,calc(100% - 160px)) !important;
  max-width:1480px !important;
  margin-left:auto !important;
  margin-right:auto !important;
  padding-inline:0 !important;
}
@media(max-width:1440px){
  .insights-topic-nav .container{
    width:calc(100% - 112px) !important;
    max-width:none !important;
    padding-inline:32px !important;
  }
}
@media(max-width:1100px){
  .insights-topic-nav .container{
    width:calc(100% - 48px) !important;
    padding-inline:0 !important;
  }
}
@media(max-width:620px){
  .insights-topic-nav .container{
    width:calc(100% - 40px) !important;
    padding-inline:0 !important;
  }
}
</style>
'''

s = s.replace('</head>', override + '\n</head>', 1)
path.write_text(s, encoding='utf-8')
